package main
import (
. "agones.dev/agones/pkg/apis/agones/v1"
apis "agones.dev/agones/pkg/apis"
assert "github.com/stretchr/testify/assert"
captureFMT "fmt"
captureJSON "encoding/json"
captureSORT "sort"
corev1 "k8s.io/api/core/v1"
pkg "agones.dev/agones/pkg"
runtime "agones.dev/agones/pkg/util/runtime"
)
type captureTestingT struct{}
func (captureTestingT) Errorf(f string,args ...interface{}) {panic(captureFMT.Sprintf(f,args...))}
func main(){captureT:=captureTestingT{}
defaultGameServerAnd := func(f func(gss *GameServerSpec)) GameServer {
	gs := GameServer{
		Spec: GameServerSpec{
			Ports:	[]GameServerPort{{ContainerPort: 999}},
			Template: corev1.PodTemplateSpec{
				Spec: corev1.PodSpec{Containers: []corev1.Container{
					{Name: "testing", Image: "testing/image"},
				}},
			},
		},
	}
	f(&gs.Spec)
	return gs
}
type expected struct {
	container		string
	protocol		corev1.Protocol
	state			GameServerState
	policy			PortPolicy
	portRange		string
	health			Health
	scheduling		apis.SchedulingStrategy
	sdkServer		SdkServer
	alphaPlayerCapacity	*int64
	counterSpec		map[string]CounterStatus
	listSpec		map[string]ListStatus
	evictionSafeSpec	EvictionSafe
	evictionSafeStatus	EvictionSafe
}
wantDefaultAnd := func(f func(e *expected)) expected {
	e := expected{
		container:	"testing",
		protocol:	"UDP",
		portRange:	DefaultPortRange,
		state:		GameServerStatePortAllocation,
		policy:		Dynamic,
		scheduling:	apis.Packed,
		health: Health{
			Disabled:		false,
			FailureThreshold:	3,
			InitialDelaySeconds:	5,
			PeriodSeconds:		5,
		},
		sdkServer: SdkServer{
			LogLevel:	SdkServerLogLevelInfo,
			GRPCPort:	9357,
			HTTPPort:	9358,
		},
		evictionSafeSpec:	EvictionSafeNever,
		evictionSafeStatus:	EvictionSafeNever,
	}
	f(&e)
	return e
}
data := map[string]struct {
	gameServer	GameServer
	container	string
	featureFlags	string
	expected	expected
}{
	"set basic defaults on a very simple gameserver": {
		gameServer:	defaultGameServerAnd(func(_ *GameServerSpec) {}),
		expected:	wantDefaultAnd(func(_ *expected) {}),
	},
	"CountsAndLists=true, Counters": {
		featureFlags:	string(runtime.FeatureCountsAndLists) + "=true",
		gameServer: defaultGameServerAnd(func(gss *GameServerSpec) {
			gss.Counters = make(map[string]CounterStatus)
			gss.Counters["games"] = CounterStatus{Count: 1, Capacity: 100}
		}),
		expected: wantDefaultAnd(func(e *expected) {
			e.counterSpec = make(map[string]CounterStatus)
			e.counterSpec["games"] = CounterStatus{Count: 1, Capacity: 100}
		}),
	},
	"CountsAndLists=true, Lists": {
		featureFlags:	string(runtime.FeatureCountsAndLists) + "=true",
		gameServer: defaultGameServerAnd(func(gss *GameServerSpec) {
			gss.Lists = make(map[string]ListStatus)
			gss.Lists["players"] = ListStatus{Capacity: 100, Values: []string{"foo", "bar"}}
		}),
		expected: wantDefaultAnd(func(e *expected) {
			e.listSpec = make(map[string]ListStatus)
			e.listSpec["players"] = ListStatus{Capacity: 100, Values: []string{"foo", "bar"}}
		}),
	},
	"defaults on passthrough": {
		gameServer: defaultGameServerAnd(func(gss *GameServerSpec) {
			gss.Ports[0].PortPolicy = Passthrough
		}),
		expected: wantDefaultAnd(func(e *expected) {
			e.policy = Passthrough
		}),
	},
	"defaults are already set": {
		gameServer: GameServer{
			Spec: GameServerSpec{
				Container:	"testing2",
				Ports: []GameServerPort{{
					Protocol:	"TCP",
					Range:		DefaultPortRange,
					PortPolicy:	Static,
				}},
				Health: Health{
					Disabled:		false,
					PeriodSeconds:		12,
					InitialDelaySeconds:	11,
					FailureThreshold:	10,
				},
				Template: corev1.PodTemplateSpec{
					Spec: corev1.PodSpec{
						Containers: []corev1.Container{
							{Name: "testing", Image: "testing/image"},
							{Name: "testing2", Image: "testing/image2"},
						},
					},
				},
				SdkServer: SdkServer{
					LogLevel:	SdkServerLogLevelInfo,
					GRPCPort:	9357,
					HTTPPort:	9358,
				},
			},
			Status:	GameServerStatus{State: "TestState"},
		},
		expected: wantDefaultAnd(func(e *expected) {
			e.container = "testing2"
			e.protocol = "TCP"
			e.state = "TestState"
			e.health = Health{
				Disabled:		false,
				FailureThreshold:	10,
				InitialDelaySeconds:	11,
				PeriodSeconds:		12,
			}
		}),
	},
	"set basic defaults on static gameserver": {
		gameServer: defaultGameServerAnd(func(gss *GameServerSpec) {
			gss.Ports[0].PortPolicy = Static
		}),
		expected: wantDefaultAnd(func(e *expected) {
			e.state = GameServerStateCreating
			e.policy = Static
		}),
	},
	"health is disabled": {
		gameServer: defaultGameServerAnd(func(gss *GameServerSpec) {
			gss.Health = Health{Disabled: true}
		}),
		expected: wantDefaultAnd(func(e *expected) {
			e.health = Health{Disabled: true}
		}),
	},
	"convert from legacy single port to multiple": {
		gameServer: defaultGameServerAnd(func(gss *GameServerSpec) {
			gss.Ports[0] = GameServerPort{
				ContainerPort:	777,
				HostPort:	777,
				PortPolicy:	Static,
				Protocol:	corev1.ProtocolTCP,
			}
		}),
		expected: wantDefaultAnd(func(e *expected) {
			e.protocol = "TCP"
			e.state = GameServerStateCreating
		}),
	},
	"set Debug logging level": {
		gameServer: defaultGameServerAnd(func(gss *GameServerSpec) {
			gss.SdkServer = SdkServer{LogLevel: SdkServerLogLevelDebug}
		}),
		expected: wantDefaultAnd(func(e *expected) {
			e.sdkServer.LogLevel = SdkServerLogLevelDebug
		}),
	},
	"set gRPC and HTTP ports on SDK Server": {
		gameServer: defaultGameServerAnd(func(gss *GameServerSpec) {
			gss.SdkServer = SdkServer{
				LogLevel:	SdkServerLogLevelError,
				GRPCPort:	19357,
				HTTPPort:	19358,
			}
		}),
		expected: wantDefaultAnd(func(e *expected) {
			e.sdkServer = SdkServer{
				LogLevel:	SdkServerLogLevelError,
				GRPCPort:	19357,
				HTTPPort:	19358,
			}
		}),
	},
	"defaults are eviction.safe: Never": {
		gameServer:	defaultGameServerAnd(func(_ *GameServerSpec) {}),
		expected: wantDefaultAnd(func(e *expected) {
			e.evictionSafeSpec = EvictionSafeNever
			e.evictionSafeStatus = EvictionSafeNever
		}),
	},
	"eviction.safe: Always": {
		gameServer: defaultGameServerAnd(func(gss *GameServerSpec) {
			gss.Eviction = &Eviction{Safe: EvictionSafeAlways}
		}),
		expected: wantDefaultAnd(func(e *expected) {
			e.evictionSafeSpec = EvictionSafeAlways
			e.evictionSafeStatus = EvictionSafeAlways
		}),
	},
	"eviction.safe: OnUpgrade": {
		gameServer: defaultGameServerAnd(func(gss *GameServerSpec) {
			gss.Eviction = &Eviction{Safe: EvictionSafeOnUpgrade}
		}),
		expected: wantDefaultAnd(func(e *expected) {
			e.evictionSafeSpec = EvictionSafeOnUpgrade
			e.evictionSafeStatus = EvictionSafeOnUpgrade
		}),
	},
	"eviction.safe: Never": {
		gameServer: defaultGameServerAnd(func(gss *GameServerSpec) {
			gss.Eviction = &Eviction{Safe: EvictionSafeNever}
		}),
		expected: wantDefaultAnd(func(e *expected) {
			e.evictionSafeSpec = EvictionSafeNever
			e.evictionSafeStatus = EvictionSafeNever
		}),
	},
	"eviction.safe: Always inferred from safe-to-evict=true": {
		gameServer: defaultGameServerAnd(func(gss *GameServerSpec) {
			gss.Template.ObjectMeta.Annotations = map[string]string{PodSafeToEvictAnnotation: "true"}
		}),
		expected: wantDefaultAnd(func(e *expected) {
			e.evictionSafeSpec = EvictionSafeNever
			e.evictionSafeStatus = EvictionSafeAlways
		}),
	},
	"Nothing inferred from safe-to-evict=false": {
		gameServer: defaultGameServerAnd(func(gss *GameServerSpec) {
			gss.Template.ObjectMeta.Annotations = map[string]string{PodSafeToEvictAnnotation: "false"}
		}),
		expected: wantDefaultAnd(func(e *expected) {
			e.evictionSafeSpec = EvictionSafeNever
			e.evictionSafeStatus = EvictionSafeNever
		}),
	},
	"safe-to-evict=false AND eviction.safe: Always => eviction.safe: Always": {
		gameServer: defaultGameServerAnd(func(gss *GameServerSpec) {
			gss.Eviction = &Eviction{Safe: EvictionSafeAlways}
			gss.Template.ObjectMeta.Annotations = map[string]string{PodSafeToEvictAnnotation: "false"}
		}),
		expected: wantDefaultAnd(func(e *expected) {
			e.evictionSafeSpec = EvictionSafeAlways
			e.evictionSafeStatus = EvictionSafeAlways
		}),
	},
}
runtime.FeatureTestMutex.Lock();defer runtime.FeatureTestMutex.Unlock()
keys:=make([]string,0,len(data));for name:=range data {keys=append(keys,name)};captureSORT.Strings(keys)
rows:=[]map[string]interface{}{}
for _,name:=range keys {test:=data[name]
before,captureErr:=captureJSON.Marshal(test.gameServer);if captureErr!=nil {panic(captureErr)}
assertions:=[]map[string]interface{}{}
record:=func(line int,kind string,expected,actual interface{},passed bool){if !passed {panic("source assertion failed")};assertions=append(assertions,map[string]interface{}{"line":line,"kind":kind,"expected":expected,"observed":actual,"source_passed":passed})}
err := runtime.ParseFeatures(test.featureFlags)
record(405,"NoError",nil,err,assert.NoError(captureT, err))
test.gameServer.ApplyDefaults()
record(409,"Equal",pkg.Version,test.gameServer.Annotations[VersionAnnotation],assert.Equal(captureT, pkg.Version, test.gameServer.Annotations[VersionAnnotation]))
spec := test.gameServer.Spec
record(412,"Contains",FinalizerName,test.gameServer.ObjectMeta.Finalizers,assert.Contains(captureT, test.gameServer.ObjectMeta.Finalizers, FinalizerName))
record(413,"Equal",test.expected.container,spec.Container,assert.Equal(captureT, test.expected.container, spec.Container))
record(414,"Equal",test.expected.protocol,spec.Ports[0].Protocol,assert.Equal(captureT, test.expected.protocol, spec.Ports[0].Protocol))
record(415,"Equal",test.expected.portRange,spec.Ports[0].Range,assert.Equal(captureT, test.expected.portRange, spec.Ports[0].Range))
record(416,"Equal",test.expected.state,test.gameServer.Status.State,assert.Equal(captureT, test.expected.state, test.gameServer.Status.State))
record(417,"Equal",test.expected.scheduling,test.gameServer.Spec.Scheduling,assert.Equal(captureT, test.expected.scheduling, test.gameServer.Spec.Scheduling))
record(418,"Equal",test.expected.health,test.gameServer.Spec.Health,assert.Equal(captureT, test.expected.health, test.gameServer.Spec.Health))
record(419,"Equal",test.expected.sdkServer,test.gameServer.Spec.SdkServer,assert.Equal(captureT, test.expected.sdkServer, test.gameServer.Spec.SdkServer))
if test.expected.alphaPlayerCapacity != nil {
record(421,"Equal",*test.expected.alphaPlayerCapacity,test.gameServer.Status.Players.Capacity,assert.Equal(captureT, *test.expected.alphaPlayerCapacity, test.gameServer.Status.Players.Capacity))
} else {
record(423,"Nil",nil,test.gameServer.Spec.Players,assert.Nil(captureT, test.gameServer.Spec.Players))
record(424,"Nil",nil,test.gameServer.Status.Players,assert.Nil(captureT, test.gameServer.Status.Players))
}
if len(test.expected.evictionSafeSpec) > 0 {
record(427,"Equal",test.expected.evictionSafeSpec,spec.Eviction.Safe,assert.Equal(captureT, test.expected.evictionSafeSpec, spec.Eviction.Safe))
} else {
record(429,"Nil",nil,spec.Eviction,assert.Nil(captureT, spec.Eviction))
}
if len(test.expected.evictionSafeStatus) > 0 {
record(432,"Equal",test.expected.evictionSafeStatus,test.gameServer.Status.Eviction.Safe,assert.Equal(captureT, test.expected.evictionSafeStatus, test.gameServer.Status.Eviction.Safe))
} else {
record(434,"Nil",nil,test.gameServer.Status.Eviction,assert.Nil(captureT, test.gameServer.Status.Eviction))
}
if test.expected.counterSpec != nil {
record(437,"Equal",test.expected.counterSpec,test.gameServer.Status.Counters,assert.Equal(captureT, test.expected.counterSpec, test.gameServer.Status.Counters))
} else {
record(439,"Nil",nil,test.gameServer.Spec.Counters,assert.Nil(captureT, test.gameServer.Spec.Counters))
record(440,"Nil",nil,test.gameServer.Status.Counters,assert.Nil(captureT, test.gameServer.Status.Counters))
}
if test.expected.listSpec != nil {
record(443,"Equal",test.expected.listSpec,test.gameServer.Status.Lists,assert.Equal(captureT, test.expected.listSpec, test.gameServer.Status.Lists))
} else {
record(445,"Nil",nil,test.gameServer.Spec.Lists,assert.Nil(captureT, test.gameServer.Spec.Lists))
record(446,"Nil",nil,test.gameServer.Status.Lists,assert.Nil(captureT, test.gameServer.Status.Lists))
}
rows=append(rows,map[string]interface{}{"name":name,"before":captureJSON.RawMessage(before),"after":test.gameServer,"feature_flags":test.featureFlags,"assertions":assertions,"expected_context":map[string]interface{}{"alpha_capacity":test.expected.alphaPlayerCapacity,"eviction_spec":test.expected.evictionSafeSpec,"eviction_status":test.expected.evictionSafeStatus,"counter_spec":test.expected.counterSpec,"list_spec":test.expected.listSpec}})}
encoded,err:=captureJSON.Marshal(rows);if err!=nil {panic(err)};captureFMT.Println(string(encoded))}
